import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

public class Solution {
    enum Status { OK, PRECO_INDISPONIVEL, ESTOQUE_INDISPONIVEL, INDISPONIVEL }

    record Resumo(String produtoId, long precoCentavos, int estoque, Status status) {}

    interface PrecoClient {
        CompletableFuture<Long> buscarPreco(String produtoId);
    }

    interface EstoqueClient {
        CompletableFuture<Integer> buscarEstoque(String produtoId);
    }

    private record Resultado<T>(T valor, boolean ok) {}

    static class CatalogoService {
        private final PrecoClient preco;
        private final EstoqueClient estoque;

        CatalogoService(PrecoClient preco, EstoqueClient estoque) {
            this.preco = preco;
            this.estoque = estoque;
        }

        CompletableFuture<Resumo> resumir(String produtoId, Duration timeout) {
            if (produtoId == null || produtoId.isBlank()) {
                throw new IllegalArgumentException("produtoId obrigatorio");
            }
            if (timeout == null || timeout.isZero() || timeout.isNegative()) {
                throw new IllegalArgumentException("timeout deve ser positivo");
            }

            var precoFuture = chamar(() -> preco.buscarPreco(produtoId), timeout);
            var estoqueFuture = chamar(() -> estoque.buscarEstoque(produtoId), timeout);

            return precoFuture.thenCombine(estoqueFuture, (p, e) -> {
                long precoFinal = p.ok() ? p.valor() : 0L;
                int estoqueFinal = e.ok() ? e.valor() : 0;
                Status status;
                if (p.ok() && e.ok()) {
                    status = Status.OK;
                } else if (!p.ok() && !e.ok()) {
                    status = Status.INDISPONIVEL;
                } else if (!p.ok()) {
                    status = Status.PRECO_INDISPONIVEL;
                } else {
                    status = Status.ESTOQUE_INDISPONIVEL;
                }
                return new Resumo(produtoId, precoFinal, estoqueFinal, status);
            });
        }

        CompletableFuture<List<Resumo>> resumirTodos(
                List<String> ids, Duration timeout, int maxConcorrencia) {
            if (ids == null) {
                throw new IllegalArgumentException("ids obrigatorios");
            }
            if (maxConcorrencia <= 0) {
                throw new IllegalArgumentException("maxConcorrencia deve ser positivo");
            }
            for (var id : ids) {
                if (id == null || id.isBlank()) {
                    throw new IllegalArgumentException("id invalido na lista");
                }
            }
            var copia = List.copyOf(ids);
            return processarLote(copia, 0, timeout, maxConcorrencia, new ArrayList<>());
        }

        private CompletableFuture<List<Resumo>> processarLote(
                List<String> ids, int inicio, Duration timeout, int maxConcorrencia,
                List<Resumo> acumulado) {
            if (inicio >= ids.size()) {
                return CompletableFuture.completedFuture(List.copyOf(acumulado));
            }
            int fim = Math.min(inicio + maxConcorrencia, ids.size());
            var lote = new ArrayList<CompletableFuture<Resumo>>(fim - inicio);
            for (int i = inicio; i < fim; i++) {
                lote.add(resumir(ids.get(i), timeout));
            }
            return CompletableFuture.allOf(lote.toArray(CompletableFuture[]::new))
                    .thenCompose(ignored -> {
                        for (var future : lote) {
                            acumulado.add(future.join());
                        }
                        return processarLote(ids, fim, timeout, maxConcorrencia, acumulado);
                    });
        }

        private <T> CompletableFuture<Resultado<T>> chamar(
                Supplier<CompletableFuture<T>> chamada, Duration timeout) {
            try {
                var future = chamada.get();
                if (future == null) {
                    return CompletableFuture.completedFuture(new Resultado<>(null, false));
                }
                return future
                        .orTimeout(timeout.toMillis(), TimeUnit.MILLISECONDS)
                        .handle((valor, erro) -> new Resultado<>(valor, erro == null && valor != null));
            } catch (RuntimeException erroSincrono) {
                return CompletableFuture.completedFuture(new Resultado<>(null, false));
            }
        }
    }
}

