import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.time.Duration;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

class SolutionTest {
    private static Solution.CatalogoService service(long preco, int estoque) {
        return new Solution.CatalogoService(
                id -> CompletableFuture.completedFuture(preco),
                id -> CompletableFuture.completedFuture(estoque));
    }

    @Test void sucessoCombinaPrecoEEstoque() throws Exception {
        var resumo = service(1290, 7).resumir("p1", Duration.ofSeconds(1))
                .get(1, TimeUnit.SECONDS);

        assertEquals(new Solution.Resumo("p1", 1290, 7, Solution.Status.OK), resumo);
    }

    @Test void precoIndisponivelMantemEstoque() throws Exception {
        var s = new Solution.CatalogoService(
                id -> CompletableFuture.failedFuture(new RuntimeException("fora")),
                id -> CompletableFuture.completedFuture(4));

        var resumo = s.resumir("p1", Duration.ofSeconds(1)).get(1, TimeUnit.SECONDS);

        assertEquals(0, resumo.precoCentavos());
        assertEquals(4, resumo.estoque());
        assertEquals(Solution.Status.PRECO_INDISPONIVEL, resumo.status());
    }

    @Test void estoqueIndisponivelMantemPreco() throws Exception {
        var s = new Solution.CatalogoService(
                id -> CompletableFuture.completedFuture(900L),
                id -> CompletableFuture.failedFuture(new RuntimeException("fora")));

        var resumo = s.resumir("p1", Duration.ofSeconds(1)).get(1, TimeUnit.SECONDS);

        assertEquals(900, resumo.precoCentavos());
        assertEquals(0, resumo.estoque());
        assertEquals(Solution.Status.ESTOQUE_INDISPONIVEL, resumo.status());
    }

    @Test void ambasAsFontesIndisponiveis() throws Exception {
        var s = new Solution.CatalogoService(
                id -> CompletableFuture.failedFuture(new RuntimeException("preco")),
                id -> CompletableFuture.failedFuture(new RuntimeException("estoque")));

        var resumo = s.resumir("p1", Duration.ofSeconds(1)).get(1, TimeUnit.SECONDS);

        assertEquals(0, resumo.precoCentavos());
        assertEquals(0, resumo.estoque());
        assertEquals(Solution.Status.INDISPONIVEL, resumo.status());
    }

    @Test void timeoutViraIndisponibilidade() throws Exception {
        var s = new Solution.CatalogoService(
                id -> new CompletableFuture<>(),
                id -> CompletableFuture.completedFuture(3));

        var resumo = s.resumir("p1", Duration.ofMillis(50)).get(1, TimeUnit.SECONDS);

        assertEquals(0, resumo.precoCentavos());
        assertEquals(3, resumo.estoque());
        assertEquals(Solution.Status.PRECO_INDISPONIVEL, resumo.status());
    }

    @Test void excecaoSincronaDoClientViraIndisponibilidade() throws Exception {
        var s = new Solution.CatalogoService(
                id -> { throw new IllegalStateException("config invalida"); },
                id -> CompletableFuture.completedFuture(1));

        var resumo = s.resumir("p1", Duration.ofSeconds(1)).get(1, TimeUnit.SECONDS);

        assertEquals(Solution.Status.PRECO_INDISPONIVEL, resumo.status());
        assertEquals(1, resumo.estoque());
    }

    @Test void lotePreservaOrdemELimitaConcorrencia() throws Exception {
        var ativos = new AtomicInteger();
        var maximo = new AtomicInteger();
        var preco = (Solution.PrecoClient) id -> CompletableFuture.supplyAsync(() -> {
            int agora = ativos.incrementAndGet();
            maximo.accumulateAndGet(agora, Math::max);
            try {
                Thread.sleep(20);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                ativos.decrementAndGet();
            }
            return 100L;
        });
        var s = new Solution.CatalogoService(
                preco, id -> CompletableFuture.completedFuture(1));

        var ids = List.of("a", "b", "c", "d", "e");
        var resumos = s.resumirTodos(ids, Duration.ofSeconds(2), 2)
                .get(5, TimeUnit.SECONDS);

        assertEquals(ids, resumos.stream().map(Solution.Resumo::produtoId).toList());
        assertTrue(maximo.get() <= 2, "concorrencia maxima observada: " + maximo.get());
        assertTrue(resumos.stream().allMatch(r -> r.status() == Solution.Status.OK));
    }

    @Test void argumentosInvalidosSaoRejeitados() {
        var s = service(1, 1);

        assertThrows(IllegalArgumentException.class,
                () -> s.resumir(" ", Duration.ofSeconds(1)));
        assertThrows(IllegalArgumentException.class,
                () -> s.resumir("p1", Duration.ZERO));
        assertThrows(IllegalArgumentException.class,
                () -> s.resumirTodos(List.of("p1"), Duration.ofSeconds(1), 0));
        assertThrows(IllegalArgumentException.class,
                () -> s.resumirTodos(Arrays.asList("p1", null), Duration.ofSeconds(1), 2));
    }
}
